    internal InnerDataAutomationProjectSplitterConfigurationFactory SplitterFactory { get; set; }

    internal InnerDataAutomationProjectModalityProcessingConfigurationFactory ModalityProcessingFactory { get; set; }

    protected override Humidifier.Bedrock.DataAutomationProjectTypes.DocumentOverrideConfiguration Create()
    {
        var documentOverrideConfigurationResult = CreateDocumentOverrideConfiguration();
        factoryAction?.Invoke(documentOverrideConfigurationResult);

        return documentOverrideConfigurationResult;
    }

    private Humidifier.Bedrock.DataAutomationProjectTypes.DocumentOverrideConfiguration CreateDocumentOverrideConfiguration()
    {
        var documentOverrideConfigurationResult = new Humidifier.Bedrock.DataAutomationProjectTypes.DocumentOverrideConfiguration();

        return documentOverrideConfigurationResult;
    }
    public override void CreateChildren(Humidifier.Bedrock.DataAutomationProjectTypes.DocumentOverrideConfiguration result)
    {
        base.CreateChildren(result);

        result.SensitiveDataConfiguration ??= SensitiveDataConfigurationFactory?.Build();
        result.Splitter ??= SplitterFactory?.Build();
        result.ModalityProcessing ??= ModalityProcessingFactory?.Build();
    }

} // End Of Class

